insert into public.questions (id, topic_id, prompt, options, answer_index, sort_order) values
  ('turkce-01', 'topic-turkce', '''Kalemlik, evimizin en güzel köşesindeydi.'' cümlesinde altı çizili sözcüğün (''kalemlik'') yapım eki hangi tür sözcük türetmiştir?', '["İsimden isim yapım eki ile isim türetilmiştir", "Fiilden isim yapım eki ile isim türetilmiştir", "İsimden fiil yapım eki ile fiil türetilmiştir", "Fiilden fiil yapım eki ile fiil türetilmiştir"]'::jsonb, 0, 1),
  ('turkce-02', 'topic-turkce', 'Aşağıdaki cümlelerin hangisinde büyük ünlü uyumuna aykırı bir sözcük vardır?', '["Kardeşim yarın okula erken gidecek.", "Kitaplığa yeni kitaplar geldi.", "Televizyon programını izledik.", "Bahçedeki güller açmış."]'::jsonb, 2, 2),
  ('turkce-03', 'topic-turkce', '''Kitab-kitabı, ağaç-ağacı'' örneklerinde görülen ses olayı aşağıdakilerden hangisidir?', '["Ünlü daralması", "Ünsüz benzeşmesi", "Ünsüz yumuşaması", "Ünlü düşmesi"]'::jsonb, 2, 3),
  ('turkce-04', 'topic-turkce', '''Öğretmenimiz bize çok değerli bilgiler öğretti ve bizi bilgilendirdi.'' cümlesindeki anlatım bozukluğunun türü nedir?', '["Özne eksikliği", "Anlamca çelişen (gereksiz tekrar/eş anlamlı sözcük) kullanımı", "Yüklem eksikliği", "Zaman uyuşmazlığı"]'::jsonb, 1, 4),
  ('turkce-05', 'topic-turkce', '''Sınava hazırlanan ve başarılı olmak isteyen öğrenciler, düzenli çalışmalı.'' cümlesinde ''öğrenciler'' sözcüğü cümlenin hangi ögesidir?', '["Nesne", "Özne", "Dolaylı tümleç", "Zarf tümleci"]'::jsonb, 1, 5),
  ('turkce-06', 'topic-turkce', 'Aşağıdaki cümlelerin hangisinde noktalama işareti yanlış kullanılmıştır?', '["Ali, sınavdan yüksek not aldı.", "\"Yarın geleceğim\" dedi.", "Kitabı okudum ve; çok beğendim.", "Ankara, Türkiye''nin başkentidir."]'::jsonb, 2, 6),
  ('turkce-07', 'topic-turkce', '''Bu konuda sana katılmıyorum, çünkü sen olayın sadece bir yönünü görüyorsun.'' cümlesinde ''çünkü'' bağlacı cümleye ne tür bir anlam katar?', '["Karşılaştırma", "Sebep-sonuç", "Amaç", "Koşul"]'::jsonb, 1, 7),
