  ('bagli-mevzuat-memur-01', 'bagli-mevzuat-memur', 'MEB Personelinin Görevde Yükselme ve Unvan Değişikliği Yönetmeliği''nin temel amacı nedir?', '["Liyakat ve kariyer ilkeleri çerçevesinde atama usul/esaslarını belirlemek", "Sadece maaş zammını düzenlemek", "Sadece izin sürelerini belirlemek", "Sadece disiplin cezalarını belirlemek"]'::jsonb, 0, 1),
  ('bagli-mevzuat-memur-02', 'bagli-mevzuat-memur', 'Görevde yükselme sınavı hangi yöntemle yapılır?', '["Yazılı sınav (ve gerekirse sözlü sınav) ile", "Sadece kıdeme göre", "Sadece mülakatla", "Kura ile"]'::jsonb, 0, 2),
  ('bagli-mevzuat-memur-03', 'bagli-mevzuat-memur', 'Aday memurların yetiştirilmesindeki temel eğitim aşamalarından biri değildir?', '["Temel eğitim", "Hazırlayıcı eğitim", "Staj", "Emeklilik eğitimi"]'::jsonb, 3, 3),
  ('bagli-mevzuat-memur-04', 'bagli-mevzuat-memur', 'Aday memurluk süresi genel olarak ne kadardır?', '["1 yıldan az, 2 yıldan çok olamaz", "Sadece 6 ay", "Sadece 3 yıl", "Süre yoktur"]'::jsonb, 0, 4),
  ('bagli-mevzuat-memur-05', 'bagli-mevzuat-memur', 'Öğretmenlerin Atama ve Yer Değiştirme Yönetmeliği hangi konuyu düzenler?', '["Öğretmenlerin atanma ve yer değiştirme usul/esaslarını", "Sadece maaş bordrosunu", "Sadece izin haklarını", "Sadece emeklilik işlemlerini"]'::jsonb, 0, 5),
  ('bagli-mevzuat-memur-06', 'bagli-mevzuat-memur', 'MEB Personeli İzin Yönergesi''ne göre yıllık izin süresi temel olarak neye göre değişir?', '["Hizmet süresine göre", "Sadece unvana göre", "Sadece cinsiyete göre", "Sadece medeni duruma göre"]'::jsonb, 0, 6),
  ('bagli-mevzuat-memur-07', 'bagli-mevzuat-memur', 'Zorunlu yer değiştirme hangi durumlarda söz konusu olabilir?', '["Hizmet ihtiyacı, sağlık veya kanunda sayılan hallerde", "Hiçbir zaman", "Sadece personelin isteğiyle", "Sadece emeklilikte"]'::jsonb, 0, 7),
  ('bagli-mevzuat-memur-08', 'bagli-mevzuat-memur', 'Görevde yükselme sınavına başvuru şartlarından biri değildir?', '["İlgili unvan için öngörülen hizmet süresini tamamlamış olmak", "Disiplin cezası almamış olmak (kanunda aranan hallerde)", "Gerekli eğitim şartını taşımak", "Sadece nüfusa kayıtlı olmak"]'::jsonb, 3, 8),
  ('bagli-mevzuat-memur-09', 'bagli-mevzuat-memur', 'Aday memur, temel ve hazırlayıcı eğitimlerde başarısız olursa ne olur?', '["Kanunda öngörülen usule göre işlemleri yapılır (gerekirse ilişiği kesilebilir)", "Otomatik olarak asalet tasdik edilir", "Hiçbir işlem yapılmaz", "Doğrudan terfi eder"]'::jsonb, 0, 9),
  ('bagli-mevzuat-memur-10', 'bagli-mevzuat-memur', 'Yer değiştirme suretiyle atamalarda esas alınan ilkelerden biri nedir?', '["Hizmetin gereği ve personelin mazereti gibi hususların birlikte değerlendirilmesi", "Sadece kıdem", "Sadece kura", "Sadece unvan"]'::jsonb, 0, 10),
  ('bagli-mevzuat-sef-01', 'bagli-mevzuat-sef', 'MEB Disiplin Amirleri Yönetmeliği''nin amacı nedir?', '["Disiplin amirlerini ve disiplin cezası vermeye yetkili makamları belirlemek", "Sadece maaşları belirlemek", "Sadece izinleri belirlemek", "Sadece atamaları belirlemek"]'::jsonb, 0, 1),
  ('bagli-mevzuat-sef-02', 'bagli-mevzuat-sef', 'Bir personelin ilk disiplin amiri genel olarak kimdir?', '["Doğrudan bağlı olduğu birim amiri", "Bakan", "Vali", "Cumhurbaşkanı"]'::jsonb, 0, 2),
  ('bagli-mevzuat-sef-03', 'bagli-mevzuat-sef', 'MEB Merkez Teşkilatı İmza Yetkileri Yönergesi neyi düzenler?', '["Bakanlık makamınca hangi yazıların hangi düzeyde imzalanacağını", "Sadece bütçe onaylarını", "Sadece atama kararlarını", "Sadece izin onaylarını"]'::jsonb, 0, 3),
  ('bagli-mevzuat-sef-04', 'bagli-mevzuat-sef', 'Şef kadrosuna görevde yükselme yoluyla atanabilmek için genel şartlardan biri nedir?', '["Yönetmelikte öngörülen hizmet süresi ve sınav şartlarını taşımak", "Sadece kıdemli olmak", "Sadece lisans mezunu olmak yeterlidir, sınav aranmaz", "Hiçbir şart aranmaz"]'::jsonb, 0, 4),
  ('bagli-mevzuat-sef-05', 'bagli-mevzuat-sef', 'Disiplin cezasına itiraz nereye yapılabilir?', '["Kanunda belirtilen disiplin kuruluna veya idare mahkemesine", "Sadece Cumhurbaşkanlığına", "Sadece Sayıştaya", "İtiraz edilemez"]'::jsonb, 0, 5),
  ('bagli-mevzuat-sef-06', 'bagli-mevzuat-sef', 'Aylıktan kesme cezasını vermeye yetkili disiplin amiri genel olarak kimdir?', '["Yönetmelikte belirlenen disiplin amiri", "Sadece Bakan", "Sadece Vali", "Sadece Cumhurbaşkanı"]'::jsonb, 0, 6),
  ('bagli-mevzuat-sef-07', 'bagli-mevzuat-sef', 'MEB Öğretmenlerin Atama ve Yer Değiştirme Yönetmeliği''nde ''zorunlu hizmet bölgesi'' kavramı neyi ifade eder?', '["Hizmet ihtiyacı nedeniyle öncelikli atama yapılan bölgeleri", "Sadece büyükşehirleri", "Sadece sınır illerini", "Kavram yoktur"]'::jsonb, 0, 7),
  ('bagli-mevzuat-sef-08', 'bagli-mevzuat-sef', 'Aday memurun asaletinin tasdiki için gerekli koşullardan biri nedir?', '["Temel ve hazırlayıcı eğitim ile staj döneminde başarılı olmak", "Sadece bir yıl beklemek", "Sadece emeklilik yaşına gelmek", "Hiçbir koşul yoktur"]'::jsonb, 0, 8),
  ('bagli-mevzuat-sef-09', 'bagli-mevzuat-sef', 'MEB Personeli İzin Yönergesi''ne göre mazeret izni hangi hallerde verilebilir?', '["Yönergede sayılan haklı ve mazur sebeplerle", "Hiçbir zaman", "Sadece hastalıkta", "Sadece doğumda"]'::jsonb, 0, 9),
  ('bagli-mevzuat-sef-10', 'bagli-mevzuat-sef', 'Disiplin soruşturmasında savunma hakkı ile ilgili temel ilke nedir?', '["İlgiliye savunmasını yapabilmesi için süre verilmesi zorunludur", "Savunma alınmadan da ceza verilebilir", "Savunma sadece yazılı olmalıdır", "Savunma hakkı yoktur"]'::jsonb, 0, 10),
  ('bagli-mevzuat-sef-11', 'bagli-mevzuat-sef', 'Görevde yükselme eğitimine katılma şartlarından biri nedir?', '["Duyurulan kadro için öngörülen öğrenim ve hizmet süresi şartını taşımak", "Sadece dilekçe vermek yeterlidir", "Sadece kıdem yeterlidir", "Şart aranmaz"]'::jsonb, 0, 11),
  ('bagli-mevzuat-sef-12', 'bagli-mevzuat-sef', 'Şeflik görevinin temel niteliği nedir?', '["Kendisine bağlı birimin iş ve işlemlerini yönetmek/koordine etmek", "Sadece evrak kaydı tutmak", "Sadece temizlik işlerini yönetmek", "Sadece arşiv işleriyle ilgilenmek"]'::jsonb, 0, 12)
